window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-83938340bffef07d"]={"versions": [{"id": "FIG-83938340bffef07d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Definition der AUTOSAR-ECU-Konfigurationsparameter (AUTOSAR_TPS_ECUConfiguration). Es spezifiziert die oberste Struktur (<code>top-level structure</code>) zur Definition von BSW-Modulen und deren Parameter-Containern im Metamodell der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metamodell-Elemente und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PackageableElement</code> / <code>ARElement</code> (abstrakt): Basis-Metaklassen für paketierbare AUTOSAR-Elemente.</li>\n<li><code>EcucDefinitionCollection</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): Spezialisiert <code>ARElement</code>. Dient als Sammlung von Moduldefinitionen und referenziert über die gerichtete Assoziation <code>+module</code> (Kardinalität <code>1..*</code>) Instanzen von <code>EcucModuleDef</code>.</li>\n<li><code>EcucModuleDef</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«EcucDefinitionElement»</code>): Spezialisiert <code>ARElement</code>. Repräsentiert die Konfigurationsdefinition eines Moduls mit den Attributen:</li>\n<li><code>+ apiServicePrefix: CIdentifier [0..1]</code></li>\n<li><code>+ supportedConfigVariant: EcucConfigurationVariantEnum [0..*]</code></li>\n<li>Assoziation/Refinement <code>«atpUriDef» +refinedModuleDef 0..1</code> auf sich selbst.</li>\n<li>Besitzt über Komposition <code>+container</code> (Kardinalität <code>1..*</code>) untergeordnete Containerdefinitionen.</li>\n<li><code>EcucDefinitionElement</code> (abstrakt): Allgemeine Basis für Definitionselemente.</li>\n<li><code>EcucContainerDef</code> (Stereotyp <code>«EcucDefinitionElement»</code>): Repräsentiert Containerdefinitionen innerhalb eines Moduls mit dem Attribut:</li>\n<li><code>+ postBuildChangeable: Boolean [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Klassendiagramm ohne dynamische Ablauf- oder Sequenzinteraktionen. Es definiert die statische Struktur und Schachtelungshierarchie von Parameterelementen zur Entwurfs- und Konfigurationszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Konfigurationswerkzeuge (BSW-Generatoren, EcuExtract-Editoren) und Moduldefinitoren:</p>\n<ul class=\"fig-list\">\n<li>Eine Modulkonfigurationsdefinition (<code>EcucModuleDef</code>) muss in mindestens einer <code>EcucDefinitionCollection</code> referenziert werden und zwingend mindestens einen Wurzel-Container (<code>EcucContainerDef</code>, <code>1..*</code>) enthalten.</li>\n<li>Die Unterstützung konfigurierbarer Varianten wird über <code>supportedConfigVariant</code> deklariert; <code>apiServicePrefix</code> bestimmt optional das C-Bezeichner-Präfix generierter API-Schnittstellen.</li>\n<li>Für Containerdefinitionen definiert <code>postBuildChangeable</code>, ob Parameterwerte nach dem Kompilieren (Post-Build) änderbar sind.</li>\n</ul>"}, {"id": "FIG-7095aaf77df2e04d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Definition der AUTOSAR-ECU-Konfigurationsparameter (AUTOSAR_TPS_ECUConfiguration). Es spezifiziert die oberste Struktur (<code>top-level structure</code>) zur Definition von BSW-Modulen und deren Parameter-Containern im Metamodell der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metamodell-Elemente und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>PackageableElement</code> / <code>ARElement</code> (abstrakt): Basis-Metaklassen für paketierbare AUTOSAR-Elemente.</li>\n<li><code>EcucDefinitionCollection</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): Spezialisiert <code>ARElement</code>. Dient als Sammlung von Moduldefinitionen und referenziert über die gerichtete Assoziation <code>+module</code> (Kardinalität <code>1..*</code>) Instanzen von <code>EcucModuleDef</code>.</li>\n<li><code>EcucModuleDef</code> (Stereotypen <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«EcucDefinitionElement»</code>): Spezialisiert <code>ARElement</code>. Repräsentiert die Konfigurationsdefinition eines Moduls mit den Attributen:</li>\n<li><code>+ apiServicePrefix :CIdentifier [0..1]</code></li>\n<li><code>+ supportedConfigVariant :EcucConfigurationVariantEnum [0..*]</code></li>\n<li>Assoziation/Refinement <code>«atpUriDef» +refinedModuleDef 0..1</code> auf sich selbst.</li>\n<li>Besitzt über Komposition <code>+container</code> (Kardinalität <code>1..*</code>) untergeordnete Containerdefinitionen.</li>\n<li><code>EcucDefinitionElement</code> (abstrakt): Allgemeine Basis für Definitionselemente.</li>\n<li><code>EcucContainerDef</code> (Stereotyp <code>«EcucDefinitionElement»</code>): Repräsentiert Containerdefinitionen innerhalb eines Moduls mit den Attributen:</li>\n<li><code>+ postBuildChangeable :Boolean [0..1]</code></li>\n<li><code>+ requiresIndex :Boolean [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Klassendiagramm ohne dynamische Ablauf- oder Sequenzinteraktionen. Es definiert die statische Struktur und Schachtelungshierarchie von Parameterelementen zur Entwurfs- und Konfigurationszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Konfigurationswerkzeuge (BSW-Generatoren, EcuExtract-Editoren) und Moduldefinitoren:</p>\n<ul class=\"fig-list\">\n<li>Eine Modulkonfigurationsdefinition (<code>EcucModuleDef</code>) muss in mindestens einer <code>EcucDefinitionCollection</code> referenziert werden und zwingend mindestens einen Wurzel-Container (<code>EcucContainerDef</code>, <code>1..*</code>) enthalten.</li>\n<li>Die Unterstützung konfigurierbarer Varianten wird über <code>supportedConfigVariant</code> deklariert; <code>apiServicePrefix</code> bestimmt optional das C-Bezeichner-Präfix generierter API-Schnittstellen.</li>\n<li>Für Containerdefinitionen definiert <code>postBuildChangeable</code>, ob Parameterwerte zur Post-Build-Zeit änderbar sind, und <code>requiresIndex</code>, ob für mehrfach vorkommende Container-Instanzen ein eindeutiger Index vorgegeben werden muss.</li>\n</ul>"}], "trans": [{"from": "FIG-83938340bffef07d", "to": "FIG-7095aaf77df2e04d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>EcucContainerDef</code>: Attribut <code>+ requiresIndex :Boolean [0..1]</code> ergänzt.</li>\n</ul>"}]};
